{"implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_map = {node['id']: node for node in nodes}
    children_of = {}
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children_of.setdefault(pid, []).append(node['id'])
    all_ids = [node['id'] for node in nodes]
    all_ids.sort(key=lambda nid: (-node_map[nid]['depth'], nid))
    queue = list(all_ids)
    removed = set()
    visit_order = []
    while queue:
        nid = queue.pop(0)
        visit_order.append(nid)
        if nid in removed:
            continue
        node = node_map[nid]
        is_leaf = True
        for cid in children_of.get(nid, []):
            if cid not in removed:
                is_leaf = False
                break
        if not is_leaf:
            continue
        if not node['removable']:
            continue
        if node['utility'] > threshold:
            continue
        removed.add(nid)
        pid = node['parent']
        if pid is not None and pid not in removed:
            queue.append(pid)
    retained = [node['id'] for node in nodes if node['id'] not in removed]
    return {"retained_node_ids": retained, "visit_order": visit_order}"}
